arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
echo "x-access-token"
EOF
# Actually need to output token for password prompt; username for username prompt. Use case.
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
*) echo "" ;;
esac
EOF
chmod +x /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh git -C /home/runner/work/chandler-wt push origin HEAD:refs/heads/friend/chandler 2>&1 | tail
